#include <iostream>
#include <string>
using namespace std;

void greet() {
    cout << "Hello!" << endl;
}

void greet(string name) {
    cout << "Hello, " << name << "!" << endl;
}

void greet(string name, int times) {
    for (int i = 1; i <= times; i++) {
        cout << "Hello, " << name << "!" << endl;
    }
}

int main() {
    greet();
    greet("Amara");
    greet("Sam", 3);
    return 0;
}

