#include <iostream>
using namespace std;

// The long version: the only place the real work lives.
void printBar(int length, char symbol) {
    for (int i = 1; i <= length; i++) {
        cout << symbol;
    }
    cout << endl;
}

// The short version: supplies the symbol, then hands over.
void printBar(int length) {
    printBar(length, '*');
}

int main() {
    printBar(7);
    printBar(7, '#');
    printBar(3, '=');
    return 0;
}

