#include <iostream>
#include <string>
using namespace std;

bool isValid(int score) {
    return score >= 0 && score <= 100;
}

void report(string name, int score, bool retake) {
    if (!isValid(score)) {
        cout << name << ": " << score << " is not a valid score" << endl;
        return;
    }
    string line = name + ": " + to_string(score);
    if (retake) {
        line = line + " (retake)";
    }
    cout << line << endl;
}

// Two arguments: assume it is not a retake.
void report(string name, int score) {
    report(name, score, false);
}

int main() {
    report("Amara", 92);
    report("Sam", 92, true);
    report("Mia", 150);
    return 0;
}

